    except TypeError:
        pass
    else:
        raise AssertionError(
            'WritableStream should not be directly instantiable'
        )

    stream = ConcreteWritableStream()
    stream.write('hello')

    assert stream.contents == ['hello']
    assert isinstance(stream, WritableStream)
